            + cdy*cdy*g1(96) &
            + 2.0_dp*cdy*g1(186) &
            + g1(326)
         vbuf(211) = aby*cdy*cdy*g1(92) &
            + 2.0_dp*aby*cdy*g1(182) &
            + aby*g1(322) &
            + cdy*cdy*g1(96) &
            + 2.0_dp*cdy*g1(186) &
            + g1(326)
         vbuf(212) = aby*cdy*cdy*g1(93) &
            + 2.0_dp*aby*cdy*g1(183) &
            + aby*g1(323) &
            + cdy*cdy*g1(98) &
            + 2.0_dp*cdy*g1(188) &
            + g1(328)
         vbuf(216) = cdy*cdy*g1(100) &
            + 2.0_dp*cdy*g1(190) &
            + g1(330)
         vbuf(219) = abx*cdy*g1(124) &
            + abx*g1(244) &
            + cdy*g1(127) &
            + g1(247)
         vbuf(222) = aby*cdy*g1(124) &
            + aby*g1(244) &
            + cdy*g1(129) &
            + g1(249)
         vbuf(223) = cdy*g1(127) &
            + g1(247)
         vbuf(224) = cdy*g1(129) &
            + g1(249)
         vbuf(228) = abx*cdy*g1(144) &
            + abx*g1(274) &
            + cdy*g1(147) &
            + g1(277)
         vbuf(231) = aby*cdy*g1(144) &
            + aby*g1(274) &
            + cdy*g1(149) &
            + g1(279)
         vbuf(232) = cdy*g1(147) &
            + g1(277)
         vbuf(233) = cdy*g1(149) &
            + g1(279)
         vbuf(235) = abx*cdy*g1(152) &
            + abx*g1(282) &
            + cdy*g1(155) &
            + g1(285)
         vbuf(236) = abx*cdy*g1(153) &
            + abx*g1(283) &
            + cdy*g1(156) &
            + g1(286)
         vbuf(238) = aby*cdy*g1(152) &
            + aby*g1(282) &
            + cdy*g1(156) &
            + g1(286)
         vbuf(239) = aby*cdy*g1(153) &
            + aby*g1(283) &
            + cdy*g1(158) &
            + g1(288)
         vbuf(243) = cdy*g1(160) &
            + g1(290)
         vbuf(246) = abx*cdy*g1(174) &
            + abx*g1(314) &
            + cdy*g1(177) &
            + g1(317)
         vbuf(249) = aby*cdy*g1(174) &
            + aby*g1(314) &
            + cdy*g1(179) &
            + g1(319)
         vbuf(250) = cdy*g1(177) &
            + g1(317)
         vbuf(251) = cdy*g1(179) &
            + g1(319)
         vbuf(253) = abx*cdy*g1(182) &
            + abx*g1(322) &
            + cdy*g1(185) &
            + g1(325)
         vbuf(254) = abx*cdy*g1(183) &
            + abx*g1(323) &
            + cdy*g1(186) &
            + g1(326)
         vbuf(256) = aby*cdy*g1(182) &
            + aby*g1(322) &
            + cdy*g1(186) &
            + g1(326)
         vbuf(257) = aby*cdy*g1(183) &
            + aby*g1(323) &
            + cdy*g1(188) &
            + g1(328)
         vbuf(261) = cdy*g1(190) &
            + g1(330)
         vbuf(264) = abx*cdy*g1(194) &
            + abx*g1(334) &
            + cdy*g1(197) &
            + g1(337)
         vbuf(267) = aby*cdy*g1(194) &
            + aby*g1(334) &
            + cdy*g1(199) &
            + g1(339)
         vbuf(268) = cdy*g1(197) &
            + g1(337)
         vbuf(269) = cdy*g1(199) &
            + g1(339)
         vbuf(271) = abx*g1(252) &
            + g1(255)
         vbuf(272) = abx*g1(253) &
            + g1(256)
         vbuf(274) = aby*g1(252) &
            + g1(256)
         vbuf(275) = aby*g1(253) &
            + g1(258)
         vbuf(279) = g1(260)
         vbuf(280) = abx*g1(282) &
            + g1(285)
         vbuf(281) = abx*g1(283) &
            + g1(286)
         vbuf(283) = aby*g1(282) &
            + g1(286)
         vbuf(284) = aby*g1(283) &
            + g1(288)
         vbuf(288) = g1(290)
         vbuf(291) = abx*g1(294) &
            + g1(297)
         vbuf(294) = aby*g1(294) &
            + g1(299)
         vbuf(295) = g1(297)
         vbuf(296) = g1(299)
         vbuf(298) = abx*g1(322) &
            + g1(325)
         vbuf(299) = abx*g1(323) &
            + g1(326)
         vbuf(301) = aby*g1(322) &
            + g1(326)
         vbuf(302) = aby*g1(323) &
            + g1(328)
         vbuf(306) = g1(330)
         vbuf(309) = abx*g1(334) &
            + g1(337)
         vbuf(312) = aby*g1(334) &
            + g1(339)
         vbuf(313) = g1(337)
         vbuf(314) = g1(339)
         vbuf(316) = abx*g1(342) &
            + g1(345)
         vbuf(317) = abx*g1(343) &
            + g1(346)
         vbuf(319) = aby*g1(342) &
            + g1(346)
         vbuf(320) = aby*g1(343) &
            + g1(348)
         vbuf(324) = g1(350)

         !
         ! BLOCK-ACCUMULATED DIGESTION.
         !
         ! The previous form did six atomic updates and six scattered `dmat`
         ! loads PER CARTESIAN COMPONENT.  For (pp|pp) that is 81 components x
         ! 6 = 486 of each, per quartet, even though only six small BLOCKS of
         ! jmat and six of dmat are ever touched.
         !
         ! gpu4pyscf's rys_contract_jk.cu does it the other way round: pull the
         ! density blocks into registers once (`load_dm`), contract every
         ! component against them there (`dot_dm`), and write each output block
         ! out once.  Same arithmetic, an order of magnitude less traffic --
         ! 54 loads and 54 atomics for (pp|pp) instead of 486.
         !
         ! The degeneracy factors are per-quartet, so they collapse into one
         ! scalar applied as the components are consumed -- and so does the
         ! segment's orbit weight, which the launcher used to fold into
         ! jfac/kfac at the cost of one launch per weight (see the weight
         ! dummy's own comment above).
         ! Both are exact powers of two (the realised weight set is
         ! (0.5, 1, 2, 4), the degeneracy halves), so scaling the integral
         ! here instead of the two operator factors is bit-identical to the
         ! old form, and the component loops below are untouched.
         !
         wq = sW(seg)
         if (.not. dij) wq = wq*0.5_dp
         if (.not. dkl) wq = wq*0.5_dp
         if (.not. dpq) wq = wq*0.5_dp

         !
         ! J-ONLY DIGESTION, for kfac = 0 (a pure LDA/GGA functional, or the
         ! Coulomb-only pass of the response equations). The exchange half of
         ! the general digestion below is then four density-block gathers and
         ! four multiply-adds per component that all come out exactly
         ! 0.0_dp, plus four accumulator blocks held live for nothing. This
         ! copy drops them; its J statements are the general branch's,
         ! character for character, so every jmat element is bit-identical
         ! to what that branch would have produced. A separate branch and not
         ! a test inside the component loop: guarding the K updates per
         ! component was measured 22% slower on a hybrid (w20/6-31G* B3LYP,
         ! V100), because the test sits on the branch that is always taken.
         ! kfac is uniform over the launch, so no warp diverges here.
         !
         if (kfac == 0.0_dp) then
         do idens = 1, ndens

         do ib = 0, 2
            do ia = 0, 2
               dab(1 + ia + 3*ib) = dmat(idens, mui + ia, nuj + ib)
               jab(1 + ia + 3*ib) = 0.0_dp
            end do
         end do
         do id = 0, 5
            do ic = 0, 5
               dcd(1 + ic + 6*id) = dmat(idens, lamk + ic, sigl + id)
               jcd(1 + ic + 6*id) = 0.0_dp
            end do
         end do

         ! Spelled differently from the general branch, on purpose, and with
         ! the same arithmetic: the component index in closed form and the
         ! scaled integral inline rather than in `idx` and `sc`. A second
         ! counted loop fails to translate the Rys launch under nvfortran
         ! 26.5 ("Missing increment value", trc_pc_rys1102).
         do id = 0, 5
         do ic = 0, 5
         do ib = 0, 2
         do ia = 0, 2
            if (mod(zpa(ia) + zpb(ib) + zpc(ic) + zpd(id), 2) == 0) then
            jab(1 + ia + 3*ib) = jab(1 + ia + 3*ib) &
                                    + 4.0_dp*jfac*(wq*vbuf(1 + ia + 3*ib + 9*ic + 54*id)) &
                                    *dcd(1 + ic + 6*id)
            jcd(1 + ic + 6*id) = jcd(1 + ic + 6*id) &
                                    + 4.0_dp*jfac*(wq*vbuf(1 + ia + 3*ib + 9*ic + 54*id)) &
                                    *dab(1 + ia + 3*ib)
            end if
         end do
         end do
         end do
         end do

         do ib = 0, 2
            do ia = 0, 2
               !$acc atomic update
               jmat(idens, mui + ia, nuj + ib) = jmat(idens, mui + ia, nuj + ib) &
                                          + jab(1 + ia + 3*ib)
            end do
         end do
         do id = 0, 5
            do ic = 0, 5
               !$acc atomic update
               jmat(idens, lamk + ic, sigl + id) = jmat(idens, lamk + ic, sigl + id) &
                                            + jcd(1 + ic + 6*id)
            end do
         end do

         end do   ! idens
         else

         !
         ! BATCHED OVER DENSITIES.
         !
         ! The integral is formed once, in `vbuf`, and contracted against every
         ! density in the batch. In the coupled-perturbed equations that is the
         ! difference between one integral pass and a hundred: the dynamic
         ! polarizabilities need nine perturbations times twelve imaginary
         ! frequencies, each a Fock build on a different response density.
         !
         ! The density loop is OUTSIDE the block accumulators, not inside, and
         ! that is the whole trick. The six blocks are zeroed, filled and
         ! written per density, so REGISTER PRESSURE DOES NOT GROW WITH THE
         ! BATCH -- holding N sets of blocks at once would have cost 54 more
         ! doubles per density at (pp|pp) and 216 at (dd|dd), on a kernel
         ! already spilling. Cost is `eval + ndens*digest`, and the ceiling is
         ! one over the digestion fraction.
         !
         do idens = 1, ndens

         !
         ! jfac = 0 whenever the MD J engine forms J (always for a g basis):
         ! the Coulomb blocks are then zero-filled rather than gathered and
         ! their atomics skipped below. The component loop is left alone (a
         ! test inside it costs more than it saves, see the J-only note).
         ! jfac is uniform over the launch, so no warp diverges.
         !
         if (jfac /= 0.0_dp) then
         do ib = 0, 2
            do ia = 0, 2
               dab(1 + ia + 3*ib) = dmat(idens, mui + ia, nuj + ib)
               jab(1 + ia + 3*ib) = 0.0_dp
            end do
         end do
         do id = 0, 5
            do ic = 0, 5
               dcd(1 + ic + 6*id) = dmat(idens, lamk + ic, sigl + id)
               jcd(1 + ic + 6*id) = 0.0_dp
            end do
         end do
         else
         do ib = 0, 2
            do ia = 0, 2
               dab(1 + ia + 3*ib) = 0.0_dp
               jab(1 + ia + 3*ib) = 0.0_dp
            end do
         end do
         do id = 0, 5
            do ic = 0, 5
               dcd(1 + ic + 6*id) = 0.0_dp
               jcd(1 + ic + 6*id) = 0.0_dp
            end do
         end do
         end if
         do ic = 0, 5
            do ia = 0, 2
               dac(1 + ia + 3*ic) = dmat(idens, mui + ia, lamk + ic)
               kac(1 + ia + 3*ic) = 0.0_dp
            end do
         end do
         do id = 0, 5
            do ia = 0, 2
               dad(1 + ia + 3*id) = dmat(idens, mui + ia, sigl + id)
               kad(1 + ia + 3*id) = 0.0_dp
            end do
         end do
         do ic = 0, 5
            do ib = 0, 2
               dbc(1 + ib + 3*ic) = dmat(idens, nuj + ib, lamk + ic)
               kbc(1 + ib + 3*ic) = 0.0_dp
            end do
         end do
         do id = 0, 5
            do ib = 0, 2
               dbd(1 + ib + 3*id) = dmat(idens, nuj + ib, sigl + id)
               kbd(1 + ib + 3*id) = 0.0_dp
            end do
         end do

         idx = 0
         do id = 0, 5
         do ic = 0, 5
         do ib = 0, 2
         do ia = 0, 2
            idx = idx + 1
            if (mod(zpa(ia) + zpb(ib) + zpc(ic) + zpd(id), 2) == 0) then
            sc = wq*vbuf(idx)
            jab(1 + ia + 3*ib) = jab(1 + ia + 3*ib) &
                                    + 4.0_dp*jfac*sc*dcd(1 + ic + 6*id)
            jcd(1 + ic + 6*id) = jcd(1 + ic + 6*id) &
                                    + 4.0_dp*jfac*sc*dab(1 + ia + 3*ib)
            kac(1 + ia + 3*ic) = kac(1 + ia + 3*ic) &
                                    - kfac*sc*dbd(1 + ib + 3*id)
            kad(1 + ia + 3*id) = kad(1 + ia + 3*id) &
                                    - kfac*sc*dbc(1 + ib + 3*ic)
            kbc(1 + ib + 3*ic) = kbc(1 + ib + 3*ic) &
                                    - kfac*sc*dad(1 + ia + 3*id)
            kbd(1 + ib + 3*id) = kbd(1 + ib + 3*id) &
                                    - kfac*sc*dac(1 + ia + 3*ic)
            end if
         end do
         end do
         end do
         end do

         if (jfac /= 0.0_dp) then
         do ib = 0, 2
            do ia = 0, 2
               !$acc atomic update
               jmat(idens, mui + ia, nuj + ib) = jmat(idens, mui + ia, nuj + ib) &
                                          + jab(1 + ia + 3*ib)
            end do
         end do
         do id = 0, 5
            do ic = 0, 5
               !$acc atomic update
               jmat(idens, lamk + ic, sigl + id) = jmat(idens, lamk + ic, sigl + id) &
                                            + jcd(1 + ic + 6*id)
            end do
         end do
         end if
         do ic = 0, 5
            do ia = 0, 2
               !$acc atomic update
               jmat(idens, mui + ia, lamk + ic) = jmat(idens, mui + ia, lamk + ic) &
                                           + kac(1 + ia + 3*ic)
            end do
         end do
         do id = 0, 5
            do ia = 0, 2
               !$acc atomic update
               jmat(idens, mui + ia, sigl + id) = jmat(idens, mui + ia, sigl + id) &
                                           + kad(1 + ia + 3*id)
            end do
         end do
         do ic = 0, 5
            do ib = 0, 2
               !$acc atomic update
               jmat(idens, nuj + ib, lamk + ic) = jmat(idens, nuj + ib, lamk + ic) &
                                           + kbc(1 + ib + 3*ic)
            end do
         end do
         do id = 0, 5
            do ib = 0, 2
               !$acc atomic update
               jmat(idens, nuj + ib, sigl + id) = jmat(idens, nuj + ib, sigl + id) &
                                           + kbd(1 + ib + 3*id)
            end do
         end do

         end do   ! idens
         end if
   end subroutine pcsi1122z

